#!/usr/bin/env node
/**
 * Build the always-on rule mirror that a DeepSeek Harness session actually receives.
 *
 * Why this file exists: DSH injects workspace instructions only for the file names it already knows
 * (`AGENTS.md`, `CLAUDE.md`, `AGENTS.local.md`, `CLAUDE.local.md`), joined onto every directory from
 * the project root down to the session cwd. It never scans `.cursor/rules/`, so a Cursor session sees
 * 7 rules that a DSH session does not. The loader takes no glob, so the only way to carry
 * `alwaysApply: true` rules across is one generated file at one of those known names.
 *
 * Output is `AGENTS.local.md` at the repository root — a **default** candidate of the shipped
 * `agent-instructions` row. Nothing in the DSH profile names this file, so isolation is the file
 * itself: a repository that carries it gets its own rules, one that does not gets nothing, and no
 * repository can receive another's rules. `.cursor/rules/` stays the single source; this is a mirror.
 *
 * Only `alwaysApply: true` rules are mirrored, and that is deliberate: it is exactly the set Cursor
 * applies without being asked. Rules with `globs` stay on-demand (law-gate → agent reads them),
 * because attaching them by touched path needs a plugin on `tools/pre-execute`, not a text file.
 *
 * `AGENTS.local.md` is also the conventional hand-written local overlay, so the script refuses to
 * overwrite a file that does not start with its own marker unless `--force` is passed.
 *
 *   node scripts/build-dsh-rules.mjs          # write AGENTS.local.md
 *   node scripts/build-dsh-rules.mjs --check  # exit 1 when the file is stale or foreign
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const RULES_DIR = '.cursor/rules';
const OUT_FILE = 'AGENTS.local.md';

/** First line of every generated mirror; also the guard against clobbering a hand-written overlay. */
const GENERATED_MARKER = '<!-- generated by `node scripts/build-dsh-rules.mjs` — do not edit by hand -->';

/** Frontmatter keys that matter here; everything else is dropped from the mirror. */
const TRUTHY = new Set(['true', 'yes', 'on', '1']);

/**
 * Split a rule file into frontmatter and body.
 * @param {string} text - whole file.
 * @returns {{ data: Record<string, string>, body: string }} `data` is empty when there is no block.
 */
export function splitFrontmatter(text) {
    const normalised = text.replace(/^\uFEFF/, '').replace(/\r\n/g, '\n');
    if (!normalised.startsWith('---\n')) return { data: {}, body: normalised };
    const end = normalised.indexOf('\n---', 3);
    if (end < 0) return { data: {}, body: normalised };
    const data = {};
    for (const line of normalised.slice(4, end).split('\n')) {
        const match = /^([A-Za-z0-9_.-]+):\s*(.*)$/.exec(line.trim());
        if (match === null) continue;
        data[match[1]] = match[2].replace(/^["']|["']$/g, '').trim();
    }
    return { data, body: normalised.slice(end + 4).replace(/^\n+/, '').replace(/\n+$/, '\n') };
}

/**
 * Push a rule's own headings two levels down so they nest under the mirror's `## <rule>` heading
 * (`# Title` → `### Title`, capped at six). Fenced blocks are skipped: a `# comment` inside ```bash
 * is code, not a heading.
 * @param {string} body - rule body after frontmatter.
 * @returns {string} body with every non-fenced heading demoted.
 */
export function demoteHeadings(body) {
    let fence = null;
    return body
        .split('\n')
        .map((line) => {
            const marker = /^\s*(`{3,}|~{3,})/.exec(line);
            if (marker !== null) {
                const ticks = marker[1][0].repeat(marker[1].length);
                if (fence === null) fence = ticks;
                else if (ticks === fence) fence = null;
                return line;
            }
            if (fence !== null) return line;
            const heading = /^(#{1,5})(\s)/.exec(line);
            if (heading === null) return line;
            return `${'#'.repeat(Math.min(heading[1].length + 2, 6))}${line.slice(heading[1].length)}`;
        })
        .join('\n');
}

/**
 * @param {string} root - repository root.
 * @returns {Array<{ name: string, source: string, description: string, body: string }>}
 *   always-on rules, sorted by file name so the output is byte-stable.
 */
export function alwaysOnRules(root = ROOT) {
    const dir = path.join(root, RULES_DIR);
    let names = [];
    try {
        names = fs.readdirSync(dir).filter((name) => name.endsWith('.mdc')).sort();
    } catch {
        return [];
    }
    const rules = [];
    for (const name of names) {
        const source = `${RULES_DIR}/${name}`;
        const { data, body } = splitFrontmatter(fs.readFileSync(path.join(dir, name), 'utf8'));
        if (!TRUTHY.has((data.alwaysApply ?? '').toLowerCase())) continue;
        rules.push({
            name: name.replace(/\.mdc$/, ''),
            source,
            description: data.description ?? '',
            body,
        });
    }
    return rules;
}

/**
 * Render the mirror. Deterministic: same rules in, same bytes out.
 * @param {string} root - repository root.
 * @returns {string} markdown to write.
 */
export function renderRules(root = ROOT) {
    const rules = alwaysOnRules(root);
    const total = countRuleFiles(root);
    const lines = [
        GENERATED_MARKER,
        `<!-- source: ${RULES_DIR} rules with \`alwaysApply: true\` (${rules.length} of ${total}) -->`,
        '<!-- why: AGENTS.local.md is a default DSH instruction candidate; `.cursor/rules/` is never scanned -->',
        '',
        '# Always-on rules',
        '',
        'Mirror of the Cursor rules that apply to every session. The originals stay authoritative: edit',
        `\`${RULES_DIR}/*.mdc\`, then rerun the generator. Rules with \`globs\` are not mirrored — they are`,
        'read on demand through the law gate in `AGENTS.md`.',
        '',
    ];
    for (const rule of rules) {
        lines.push(`## ${rule.name}`, '', `source: \`${rule.source}\``);
        if (rule.description !== '') lines.push(`description: ${rule.description}`);
        lines.push('', demoteHeadings(rule.body).replace(/\n+$/, ''), '');
    }
    return lines.join('\n');
}

/** @param {string} root @returns {number} every `.mdc` in the rules directory, mirrored or not. */
function countRuleFiles(root) {
    try {
        return fs.readdirSync(path.join(root, RULES_DIR)).filter((n) => n.endsWith('.mdc')).length;
    } catch {
        return 0;
    }
}

/**
 * @param {string[]} argv - process arguments after the script name.
 * @returns {number} exit code: 0 written / up to date, 1 stale under `--check`.
 */
export function run(argv = process.argv.slice(2), root = ROOT) {
    const check = argv.includes('--check');
    const force = argv.includes('--force');
    const outPath = path.join(root, OUT_FILE);
    const rendered = renderRules(root);
    const current = fs.existsSync(outPath) ? fs.readFileSync(outPath, 'utf8') : null;
    const ruleCount = alwaysOnRules(root).length;

    /*
     * `AGENTS.local.md` is also where a person writes their own uncommitted overlay. Rewriting it
     * with generated rules would delete their notes, so anything without this script's first line is
     * treated as foreign and left alone.
     */
    if (current !== null && !current.startsWith(GENERATED_MARKER) && !force) {
        console.error(`${OUT_FILE} exists and was not written by this script — refusing to overwrite it. Move it aside, or pass --force.`);
        return 1;
    }

    if (check) {
        if (current === rendered) {
            console.log(`${OUT_FILE} is up to date (${ruleCount} always-on rules)`);
            return 0;
        }
        const stale = current === null ? 'missing' : 'stale';
        console.error(`${OUT_FILE} is ${stale}: run \`node scripts/build-dsh-rules.mjs\``);
        return 1;
    }
    if (current === rendered) {
        console.log(`${OUT_FILE} unchanged (${ruleCount} always-on rules)`);
        return 0;
    }
    fs.mkdirSync(path.dirname(outPath), { recursive: true });
    fs.writeFileSync(outPath, rendered);
    console.log(`wrote ${OUT_FILE} (${ruleCount} always-on rules, ${Buffer.byteLength(rendered)} bytes)`);
    return 0;
}

if (process.argv[1] !== undefined && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
    process.exit(run());
}
